import { isLabel, loadedAnnotation, type Annotation } from "./annotations";
import { arrayElements, member, objectMembers } from "./jsonSpans";
import { NarrativeIndex } from "./offsets";

/** A stored submission opened for annotation. */
export interface LoadedSubmission {
  readonly caseId: string;
  readonly username: string;
  readonly version: number;
  readonly submittedAt: string;
  readonly updatedAt: string;
  readonly narrative: NarrativeIndex;
  readonly userAnnotations: readonly Annotation[];
  readonly llmSets: readonly LlmSet[];
}

/** A read-only set generated by a model; its annotations are never sent back. */
export interface LlmSet {
  readonly id: string;
  readonly provider: string;
  readonly model: string;
  readonly generatedAt: string;
  readonly annotations: readonly Annotation[];
}

interface ExportHead {
  case_id: string;
  username: string;
  version: number;
  submitted_at: string;
  updated_at: string;
  record: { narrative: string };
}

interface AnnotationValues {
  text: string;
  start: number;
  end: number;
}

interface SetHead {
  provider?: string;
  model?: string;
  generated_at?: string;
}

/** Reads one annotation map at `start`, keeping each annotation's exact source text. */
function readMap(body: string, start: number): Annotation[] {
  const annotations: Annotation[] = [];
  for (const entry of objectMembers(body, start)) {
    const label = entry.name;
    if (!isLabel(label)) throw new SyntaxError("export has an unknown label");
    arrayElements(body, entry.start).forEach((span, position) => {
      const source = body.slice(span.start, span.end);
      const values = JSON.parse(source) as AnnotationValues;
      annotations.push(
        loadedAnnotation(label, values.start, values.end, values.text, source, position),
      );
    });
  }
  return annotations;
}

export function byCodePoint(a: string, b: string): number {
  const x = Array.from(a);
  const y = Array.from(b);
  for (let i = 0; i < Math.min(x.length, y.length); i += 1) {
    const d = (x[i]?.codePointAt(0) ?? 0) - (y[i]?.codePointAt(0) ?? 0);
    if (d !== 0) return d;
  }
  return x.length - y.length;
}

/**
 * Reads an export body (stage 4 §2). Field values come from `JSON.parse`; each annotation
 * also keeps its exact source text, which `JSON.parse` alone would lose (number tokens).
 */
export function parseExport(body: string): LoadedSubmission {
  const head = JSON.parse(body) as ExportHead;
  const top = objectMembers(body, body.search(/\S/));
  const record = member(top, "record");
  if (record === undefined) throw new SyntaxError("export has no record");
  const sets = member(objectMembers(body, record.start), "annotation_sets");
  const narrative = new NarrativeIndex(head.record.narrative);
  let userAnnotations: Annotation[] = [];
  const llmSets: LlmSet[] = [];
  if (sets !== undefined) {
    for (const entry of objectMembers(body, sets.start)) {
      const annotations = member(objectMembers(body, entry.start), "annotations");
      const mapped = annotations === undefined ? [] : readMap(body, annotations.start);
      if (entry.name === "user") {
        userAnnotations = mapped;
      } else {
        const values = JSON.parse(body.slice(entry.start, entry.end)) as SetHead;
        llmSets.push({
          id: entry.name,
          provider: values.provider ?? "",
          model: values.model ?? "",
          generatedAt: values.generated_at ?? "",
          annotations: mapped,
        });
      }
    }
  }
  llmSets.sort((a, b) => byCodePoint(a.id, b.id));
  return {
    caseId: head.case_id,
    username: head.username,
    version: head.version,
    submittedAt: head.submitted_at,
    updatedAt: head.updated_at,
    narrative,
    userAnnotations,
    llmSets,
  };
}
